import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/track_editor._GkiL2zB.svg",n="/llamatron/assets/track_euclid.DHO5RBMK.svg",m=JSON.parse('{"title":"Tracks","description":"","frontmatter":{},"headers":[],"relativePath":"TRACKS.md","filePath":"TRACKS.md"}'),c={name:"TRACKS.md"};function d(h,e,i,l,p,k){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="tracks" tabindex="-1">Tracks <a class="header-anchor" href="#tracks" aria-label="Permalink to &quot;Tracks&quot;">​</a></h1><p>A track is a column of Arrange, with its own instrument, transpose, CC numbers and more. This page covers the track editor, whose settings apply to every clip on the track.</p><p><img src="'+r+'" alt="A track&#39;s settings"></p><h2 id="track-settings" tabindex="-1">Track Settings <a class="header-anchor" href="#track-settings" aria-label="Permalink to &quot;Track Settings&quot;">​</a></h2><p>On Arrange, <code>Enter</code> on a track&#39;s name opens the track editor. Tracks become tracks in Live in the order Arrange shows them.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>Enter</code> renames the track, updating every scene and every clip that grabs from the track.</td></tr><tr><td>Drum</td><td>Marks a drum track, shown with <code>●</code>, which is never transposed. <code>Space</code> or <code>Enter</code> toggles it.</td></tr><tr><td>Mute</td><td>Starts the track switched off in Live, shown with <code>●</code>, so the track is silent until switched on. A muted track&#39;s clips are still written, so the track can be switched on to hear them, and other tracks can still grab notes from it. Mute is meant for tracks that only feed grabs or a hocket. <code>Space</code> or <code>Enter</code> toggles it.</td></tr><tr><td>Groove</td><td>A groove for the track&#39;s clips in place of the scene&#39;s or the song&#39;s, or <code>off</code> to play them straight whatever the scene and song choose, which keeps a kick straight in a swung song. <code>[</code> and <code>]</code> step through the choices, <code>Enter</code> picks from a list, and <code>Bksp</code> goes back to the scene&#39;s or the song&#39;s. See <a href="./GROOVES">Grooves</a>.</td></tr><tr><td>Transpose</td><td>Moves every note on the track along the scale, from -24 to 24, without changing its patterns; in a seven-note scale, 7 is an octave. Drum patterns are never transposed, on any track.</td></tr><tr><td>Lowest octave, Highest octave</td><td>The octaves the track&#39;s instrument plays, in the Set File page&#39;s octave labels, the whole MIDI range at first. The piano roll marks the rows outside them when this track alone plays a pattern. <code>[</code> and <code>]</code> move an end, which can&#39;t cross the other, <code>Enter</code> types one, and <code>Bksp</code> puts it back at the end of the range.</td></tr><tr><td>Chains</td><td>The chains every clip on the track runs, after the clip&#39;s own and the scene&#39;s, edited as a clip&#39;s are. Track chains give a whole part the same treatment, such as a strum or a slight drift; a chain named both here and on a clip runs twice. See <a href="./CHAINS">Chains</a>.</td></tr><tr><td>Instrument</td><td>The instrument the track plays through in real time, chosen from the Instruments page, or <code>(none)</code> to leave the track out of real-time playback. <code>Enter</code> chooses and <code>Bksp</code> sets none. See <a href="./INSTRUMENTS">Instruments</a>.</td></tr><tr><td>+ Euclid</td><td>A section, closed until opened, holding a Euclidean rhythm that masks every clip on the track: Euclid hits, Euclid steps, Euclid rotate and Euclid step, as <a href="./generators/EUCLID">Euclid</a> describes. <code>H</code> on Euclid hits picks a named rhythm.</td></tr><tr><td>+ Strum</td><td>A section, closed until opened, that strums every chord the track plays: Strum direction, <code>(none)</code> for no strum, and the other settings <a href="./generators/STRUM">Strum</a> describes. A clip&#39;s own strum wins over the track&#39;s.</td></tr><tr><td>CC 1 to CC 4</td><td>The CC number each of a pattern&#39;s CC rows sends on this track, from 0 to 127. <code>Bksp</code> sets none, so that the row sends nothing on this track. CC 1 is usually the mod wheel, and CC 74 the filter cutoff.</td></tr><tr><td>CC1 Reg to CC4 Reg</td><td>A register, AX to DX, bound to that CC lane, or <code>(none)</code>. A bound lane sends the register&#39;s value, held between 0 and 127, on the lane&#39;s CC number when the track&#39;s clip starts and whenever the register changes while the clip plays, so a step on any track can move this track&#39;s filter. A step&#39;s own value on the CC row wins at that step&#39;s moment. <code>[</code> and <code>]</code> step through the registers, <code>Enter</code> picks one, and <code>Bksp</code> unbinds. See <a href="./REGISTERS">Registers</a>.</td></tr><tr><td>Vel Reg</td><td>A register bound to the velocity, or <code>(none)</code>. A note whose Velocity is blank plays at the register&#39;s value, held between 1 and 127, and <code>+Vel</code> still adds to that value. The keys are the same as for the CC lanes.</td></tr></tbody></table><h2 id="euclidean-mask" tabindex="-1">Euclidean Mask <a class="header-anchor" href="#euclidean-mask" aria-label="Permalink to &quot;Euclidean Mask&quot;">​</a></h2><p>A track&#39;s <code>+ Euclid</code> section keeps only the notes that land on a Euclidean rhythm, in every clip the track plays. In <code>examples/other/euclidean.yml</code>, the shaker plays 11 hits over 16 steps:</p><p><img src="'+n+'" alt="A track&#39;s Euclid section open"></p>',9)])])}const g=t(c,[["render",d]]);export{m as __pageData,g as default};
